static bool lm_text_is_float_74000331(const char* s, int32_t n) {
    char* end = NULL;
    if (n == 0 || n >= 64 || (int32_t)strlen(s) != n) return false;
    if (s[0] == ' ' || s[0] == '\t' || s[0] == '\n' || s[0] == '\r' || s[0] == '\f' || s[0] == '\v') return false;
    (void)strtod(s, &end);
    return end == s + n;
}
static double lm_text_to_float_74000338(const char* s) {
    return strtod(s, NULL);
}
static Ext_std__lang__TextBuf lm_text_buf_new_74000347(RtMem* m) {
    TextBuf* b = (TextBuf*)rt_mem_alloc(m, sizeof(TextBuf), 0);
    b->mem = m;
    b->cap = 32;
    b->buf = (char*)rt_mem_alloc(m, (size_t)b->cap, 0);
    return b;
}
static void lm_text_buf_add_74000355(Ext_std__lang__TextBuf b, const char* text) {
    int32_t n = (int32_t)strlen(text);
    if (n > INT32_MAX - b->len) rt_panic("text is too large", 0);
    int32_t need = b->len + n + 1;
    if (need > b->cap) {
        int32_t cap = b->cap;
        while (cap < need) {
            if (cap > INT32_MAX / 2) { cap = need; break; }
            cap *= 2;
        }
        char* next = (char*)rt_mem_alloc(b->mem, (size_t)cap, 0);
        if (b->len > 0) memcpy(next, b->buf, (size_t)b->len);
        b->buf = next;
        b->cap = cap;
    }
    if (n > 0) memcpy(b->buf + b->len, text, (size_t)n);
    b->len += n;
    b->buf[b->len] = 0;
}
static int32_t lm_text_buf_length_74000375(Ext_std__lang__TextBuf b) {
    return b->len;
}
static const char* lm_text_buf_view_74000376(Ext_std__lang__TextBuf b) {
    return b->buf;
}
static void lm_text_buf_clear_74000377(Ext_std__lang__TextBuf b) {
    b->len = 0; if (b->buf) b->buf[0] = 0;
}
static Ext_std__lang__ByteText lm_byte_text_sized_74000399(RtMem* m, int32_t n) {
    ByteText* t = (ByteText*)rt_mem_alloc(m, sizeof(ByteText), 0);
    t->mem = m;
    t->capacity = (n > 0 ? n : 0) + 1;
    t->bytes = (char*)rt_mem_alloc(m, (size_t)t->capacity, 0);
    return t;
}
static void lm_byte_text_add_74000407(Ext_std__lang__ByteText t, uint8_t b) {
    if (t->length + 2 > t->capacity) {                 /* +1 for the byte, +1 for the final 0 */
        int32_t capacity = t->capacity * 2;
        char* bytes = (char*)rt_mem_alloc(t->mem, (size_t)capacity, 0);
        memcpy(bytes, t->bytes, (size_t)t->length);
        t->bytes = bytes;
        t->capacity = capacity;
    }
    t->bytes[t->length++] = (char)b;
    t->bytes[t->length] = 0;
}
static const char* lm_byte_text_view_74000419(Ext_std__lang__ByteText t) {
    return t->bytes;
}
